function phoneDigits(value){
  let digits=String(value||'').replace(/\D/g,'');
  if(digits.length===11&&digits.startsWith('1'))digits=digits.slice(1);
  return digits.slice(0,10);
}
function formatUsPhone(value){
  const digits=phoneDigits(value);
  if(!digits)return'';
  if(digits.length<4)return`+1 ${digits}`;
  if(digits.length<7)return`+1 (${digits.slice(0,3)}) ${digits.slice(3)}`;
  return`+1 (${digits.slice(0,3)}) ${digits.slice(3,6)}-${digits.slice(6,10)}`;
}
function nationalPhone(value){
  const digits=phoneDigits(value);
  if(!digits)return'';
  if(digits.length<=3)return digits;
  if(digits.length<=6)return`${digits.slice(0,3)}-${digits.slice(3)}`;
  return`${digits.slice(0,3)}-${digits.slice(3,6)}-${digits.slice(6,10)}`;
}
function smsPhone(value){
  const digits=phoneDigits(value);
  return digits.length===10?`+1${digits}`:'';
}

function setSmsStatus(message,type='info'){
  const box=$('smsStatus');
  if(!box)return;
  box.textContent=message||'';
  box.classList.remove('hidden','error','info');
  box.classList.add(type==='error'?'error':'info');
}
function clearSmsStatus(){
  const box=$('smsStatus');
  if(!box)return;
  box.textContent='';
  box.classList.add('hidden');
  box.classList.remove('error','info');
}
async function copyTextSafely(text){
  const value=String(text||'');
  if(!value)return false;

  if(navigator.clipboard&&window.isSecureContext){
    try{
      await navigator.clipboard.writeText(value);
      return true;
    }catch(error){}
  }

  const area=document.createElement('textarea');
  area.value=value;
  area.setAttribute('readonly','');
  area.style.position='fixed';
  area.style.left='-9999px';
  area.style.top='0';
  document.body.appendChild(area);
  area.focus();
  area.select();
  let copied=false;
  try{copied=document.execCommand('copy')}catch(error){copied=false}
  area.remove();
  return copied;
}
function clickExternalLink(url){
  const link=document.createElement('a');
  link.href=url;
  link.style.display='none';
  document.body.appendChild(link);
  link.click();
  setTimeout(()=>link.remove(),250);
}
function smsDeviceType(){
  const ua=navigator.userAgent||'';
  const iOS=/iPhone|iPad|iPod/i.test(ua)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
  const mac=/Macintosh|Mac OS X/i.test(ua)&&!iOS;
  const android=/Android/i.test(ua);
  return iOS?'ios':mac?'mac':android?'android':'other';
}
async function openSmsComposer(phone,body,vendorName){
  const device=smsDeviceType();
  const name=vendorName||'the vendor';
  if(!phone){
    setSmsStatus(`A complete 10-digit U.S. phone number is required for ${name}.`,'error');
    return false;
  }
  if(!String(body||'').trim()){
    setSmsStatus('Enter a message before opening the text app.','error');
    return false;
  }

  if(device==='ios'){
    const copied=await copyTextSafely(body);
    // Apple documents the recipient-only sms: format. The message is copied
    // separately so the URL is not rejected for containing unsupported text.
    clickExternalLink(`sms:${phone}`);
    setSmsStatus(
      copied
        ?`Messages was opened for ${name}. The message was copied—paste it into the message box.`
        :`Messages was opened for ${name}. Copy the message manually from the text box and paste it into Messages.`,
      'info'
    );
    return true;
  }

  if(device==='mac'){
    const copied=await copyTextSafely(body);
    setSmsStatus(
      copied
        ?`Message copied for ${name}. Open Messages on your Mac, use ${formatUsPhone(phone)} as the recipient, and paste the message. Use Copy phone if needed.`
        :`Open Messages on your Mac, enter ${formatUsPhone(phone)}, then copy the message manually from the text box.`,
      copied?'info':'error'
    );
    return copied;
  }

  if(device==='android'){
    clickExternalLink(`sms:${phone}?body=${encodeURIComponent(body)}`);
    setSmsStatus(`The text app was opened for ${name} with the message prepared.`,'info');
    return true;
  }

  const copied=await copyTextSafely(`To: ${phone}\n\n${body}`);
  setSmsStatus(
    copied
      ?`This computer does not expose a reliable SMS app link. The phone number and message were copied; paste them into your messaging app.`
      :`This computer does not expose a reliable SMS app link. Use Copy phone and Copy message, then paste them into your messaging app.`,
    copied?'info':'error'
  );
  return copied;
}
