function normalizeWebsiteUrl(value){
  const text=String(value||'').trim();
  if(!text)return'';
  const candidate=/^https?:\/\//i.test(text)?text:`https://${text.replace(/^\/+/, '')}`;
  try{
    const url=new URL(candidate);
    return ['http:','https:'].includes(url.protocol)?url.href:'';
  }catch(error){return''}
}
function websiteLabel(value){
  const url=normalizeWebsiteUrl(value);
  if(!url)return'';
  try{return new URL(url).hostname.replace(/^www\./i,'')||url}
  catch(error){return url}
}

function normalizeHalfHourTime(value,allow24=false){
  if(!value)return'';
  const match=String(value).match(/^(\d{1,2}):(\d{2})$/);
  if(!match)return'';
  let total=(Number(match[1])||0)*60+(Number(match[2])||0);
  total=Math.round(total/30)*30;
  const minimum=480;
  const maximum=allow24?1440:1410;
  total=Math.max(minimum,Math.min(maximum,total));
  if(total===1440)return'24:00';
  return`${String(Math.floor(total/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`;
}

function uid(prefix='id'){return prefix+'-'+Math.random().toString(36).slice(2,10)}
function cleanVendorBase(name){
  return String(name||'').replace(/\s*[-–]\s*boat\s*\d+\s*$/i,'').replace(/\s+boat\s*\d+\s*$/i,'').trim();
}
function vendorKey(name){return cleanVendorBase(name).toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function firstNonEmpty(items,key,def=''){for(const x of items){if(x&&x[key]!==undefined&&x[key]!==null&&x[key]!=='')return x[key]}return def}
function groupFlatRows(rows){
  const map=new Map();
  for(const row of rows||[]){
    const key=vendorKey(row.name);
    if(!map.has(key))map.set(key,[]);
    map.get(key).push(row);
  }
  return [...map.values()].map(items=>{
    const display=cleanVendorBase(firstNonEmpty(items,'name','Unnamed Vendor'));
    const yachts=items.map((r,index)=>({
      id:uid('yacht'),
      name:r.boat||((items.length>1)?`Yacht ${index+1}`:'Yacht details needed'),
      capacity:r.capacity??null,
      length:r.boatLength??null,
      price:r.hourlyPrice??null,
      category:r.category||'',
      website:r.boatLink||'',
      availability:r.availability||'Unknown',
      notes:r.notes||'',
      slots:Array.isArray(r.slots)?r.slots.map(s=>({...s})):[],
      profilePhoto:r.profilePhoto||'',
      galleryPhotos:Array.isArray(r.galleryPhotos)?[...r.galleryPhotos]:[]
    }));
    return {
      id:uid('vendor'),
      name:display,
      phone:firstNonEmpty(items,'phone',''),
      email:firstNonEmpty(items,'email',''),
      website:firstNonEmpty(items,'website',''),
      captainIncluded:firstNonEmpty(items,'captainIncluded','Unknown'),
      captainPrice:firstNonEmpty(items,'captainPrice',''),
      captainName:firstNonEmpty(items,'captainName',''),
      boardingLocation:firstNonEmpty(items,'boardingLocation',''),
      vendorCategory:firstNonEmpty(items,'vendorCategory','Not categorized'),
      sortOrder:Number(firstNonEmpty(items,'sortOrder',999))||999,
      reliabilityStatus:firstNonEmpty(items,'reliabilityStatus','Not rated'),
      overallBehavior:firstNonEmpty(items,'overallBehavior','Not rated'),
      bookingRelationship:firstNonEmpty(items,'bookingRelationship','No booking yet'),
      completedBookingCount:Number(firstNonEmpty(items,'completedBookingCount',0))||0,
      bookingHistory:[],
      notes:'',
      profilePhoto:'',
      galleryPhotos:[],
      yachts
    };
  });
}
function bookingBehaviorNumber(value){
  return {Excellent:5,Good:4,Average:3,Poor:2,Problem:1}[value]||0;
}
function deriveOverallBehavior(vendor){
  const history=Array.isArray(vendor&&vendor.bookingHistory)?vendor.bookingHistory:[];
  let rated=history.filter(item=>bookingBehaviorNumber(item&&item.behavior)>0&&item.status==='Completed');
  if(!rated.length)rated=history.filter(item=>bookingBehaviorNumber(item&&item.behavior)>0);
  if(rated.length){
    const average=rated.reduce((sum,item)=>sum+bookingBehaviorNumber(item.behavior),0)/rated.length;
    if(average>=4.5)return'Top Rated';
    if(average>=3.5)return'Good';
    if(average>=2.5)return'Average';
    if(average>=1.5)return'Poor';
    return'Problem';
  }
  if(vendor&&vendor.vendorCategory==='Top Guy')return'Top Rated';
  if(vendor&&vendor.vendorCategory==='Reliable')return'Good';
  if(vendor&&vendor.vendorCategory==='Lazy')return'Poor';
  if(vendor&&vendor.reliabilityStatus==='Responsive')return'Good';
  if(vendor&&vendor.reliabilityStatus==='Slow')return'Average';
  if(vendor&&vendor.reliabilityStatus==='Not Reliable')return'Problem';
  return'Not rated';
}
function overallBehaviorRank(value){
  return {'Top Rated':1,Good:2,Average:3,Poor:4,Problem:5,'Not rated':6}[value]||7;
}
function overallBehaviorScore(value){
  return {'Top Rated':5,Good:4,Average:3,Poor:2,Problem:1,'Not rated':0}[value]||0;
}
function overallBehaviorCss(value){
  return String(value||'Not rated').toLowerCase().replace(/\s+/g,'-');
}

function normalizeLoadedVendors(data){
  const usedVendorIds=new Set(),usedYachtIds=new Set();
  return (data||[]).map((raw,vendorIndex)=>{
    const vendor={...blankVendor(),...raw};
    if(!vendor.id||usedVendorIds.has(vendor.id))vendor.id=uid('vendor');
    usedVendorIds.add(vendor.id);
    vendor.phone=formatUsPhone(vendor.phone);
    vendor.vendorCategory=['Reliable','Lazy','Top Guy','Expensive','Not categorized'].includes(vendor.vendorCategory)?vendor.vendorCategory:'Not categorized';
    vendor.reliabilityStatus=['Responsive','Slow','Not Reliable','Not rated'].includes(vendor.reliabilityStatus)?vendor.reliabilityStatus:'Not rated';
    vendor.bookingRelationship=['No booking yet','Inquiry only','Booked before'].includes(vendor.bookingRelationship)?vendor.bookingRelationship:'No booking yet';
    vendor.completedBookingCount=Math.max(0,Math.round(Number(vendor.completedBookingCount)||0));
    vendor.bookingHistory=(Array.isArray(vendor.bookingHistory)?vendor.bookingHistory:[]).map(rawBooking=>({
      id:rawBooking&&rawBooking.id?rawBooking.id:uid('booking'),
      date:rawBooking&&rawBooking.date?rawBooking.date:'',
      yachtId:rawBooking&&rawBooking.yachtId?rawBooking.yachtId:'',
      status:['Completed','Pending','Cancelled'].includes(rawBooking&&rawBooking.status)?rawBooking.status:'Completed',
      behavior:['Not rated','Excellent','Good','Average','Poor','Problem'].includes(rawBooking&&rawBooking.behavior)?rawBooking.behavior:'Not rated',
      reference:rawBooking&&rawBooking.reference?rawBooking.reference:'',
      notes:rawBooking&&rawBooking.notes?rawBooking.notes:''
    }));
    vendor.overallBehavior=['Top Rated','Good','Average','Poor','Problem','Not rated'].includes(vendor.overallBehavior)
      ?vendor.overallBehavior
      :deriveOverallBehavior(vendor);
    const loggedCompleted=vendor.bookingHistory.filter(b=>b.status==='Completed').length;
    vendor.completedBookingCount=Math.max(vendor.completedBookingCount,loggedCompleted);
    if(vendor.completedBookingCount>0)vendor.bookingRelationship='Booked before';
    const savedOrder=Number(vendor.sortOrder);
    vendor.sortOrder=Number.isFinite(savedOrder)&&savedOrder>0?Math.round(savedOrder):vendorIndex+1;
    vendor.galleryPhotos=Array.isArray(vendor.galleryPhotos)?vendor.galleryPhotos:[];
    vendor.yachts=(Array.isArray(vendor.yachts)?vendor.yachts:[]).map(rawYacht=>{
      const yacht={...blankYacht(),...rawYacht};
      if(!yacht.id||usedYachtIds.has(yacht.id))yacht.id=uid('yacht');
      usedYachtIds.add(yacht.id);
      yacht.galleryPhotos=Array.isArray(yacht.galleryPhotos)?yacht.galleryPhotos:[];
      yacht.website=normalizeWebsiteUrl(yacht.website||'');
      yacht.slots=(Array.isArray(yacht.slots)?yacht.slots:[]).map(slot=>({
        ...slot,
        start:normalizeHalfHourTime(slot&&slot.start,false),
        end:normalizeHalfHourTime(slot&&slot.end,true)
      }));
      if(String(vendor.name).toLowerCase()==='nauti chicago'&&String(yacht.name).trim().toLowerCase()==='not working'){
        yacht.name='';
        yacht.notes='';
      }
      return yacht;
    });
    return vendor;
  });
}
function migrateLoaded(data){
  if(!Array.isArray(data))return normalizeLoadedVendors(groupFlatRows(flatDefaults));
  if(data.length&&Array.isArray(data[0].yachts))return normalizeLoadedVendors(data);
  return normalizeLoadedVendors(groupFlatRows(data));
}

