function num(v){return Number(v)||null}
function fmtTime(t){
  if(!t)return'';
  if(t==='24:00')return'12:00 AM (next day)';
  const [h,m]=t.split(':');
  const d=new Date();
  d.setHours(+h,+m);
  return d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});
}
function download(name,text,type){const b=new Blob([text],{type});const u=URL.createObjectURL(b);const a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),500)}
function csv(v){
  let text=String(v??'');
  if(/^[=+\-@]/.test(text))text=`'${text}`;
  return `"${text.replace(/"/g,'""')}"`;
}
function csvDocument(rows){return '\ufeff'+rows.map(row=>row.map(csv).join(',')).join('\n')}
function loadImageElement(file){
  return new Promise((resolve,reject)=>{
    const image=new Image();
    const url=URL.createObjectURL(file);
    image.onload=()=>{URL.revokeObjectURL(url);resolve(image)};
    image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('This picture format could not be opened. Please use JPG, PNG, or WebP.'))};
    image.src=url;
  });
}
async function compressImage(file,maxDimension=1000,quality=.68){
  if(!file||!String(file.type).startsWith('image/'))throw new Error('Please select a picture file.');
  const image=await loadImageElement(file);
  const scale=Math.min(1,maxDimension/Math.max(image.naturalWidth,image.naturalHeight));
  const width=Math.max(1,Math.round(image.naturalWidth*scale));
  const height=Math.max(1,Math.round(image.naturalHeight*scale));
  const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;
  const ctx=canvas.getContext('2d',{alpha:false});ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);ctx.drawImage(image,0,0,width,height);
  return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('The picture could not be compressed.')),'image/jpeg',quality));
}
function blobToDataUrl(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob)})}
async function saveImageFile(file){return blobToDataUrl(await compressImage(file))}
