function bookingAttentionIssues(record){
  const issues=[];
  const add=(code,type,label)=>issues.push({code,type,label});

  if(!String(record.clientName||'').trim())add('client-name','client','Client name is missing');
  if(!String(record.clientPhone||'').trim()&&!String(record.clientEmail||'').trim())add('client-contact','client','Client phone or email is missing');
  if(!record.date)add('trip-date','time','Trip date is missing');
  if(!record.start)add('start-time','time','Start time is missing');
  if(!record.end)add('end-time','time','End time is missing');
  if(record.start&&record.end&&availabilityHours(record.start,record.end)<=0)add('invalid-time','time','The booking end time is not later than the start time');
  if(!Number(record.guestCount))add('guest-count','client','Guest count is missing');
  if(!record.vendorId)add('vendor','assignment','Vendor has not been assigned');
  if(!record.yachtId)add('yacht','assignment','Yacht has not been assigned');
  if(!Number(record.customerTotal)&&!Number(record.customerHourly))add('customer-price','financial','Customer price is missing');
  if(record.vendorId&&!Number(record.vendorHourly))add('vendor-price','financial','Vendor hourly cost is missing');
  if(record.paymentStatus==='Deposit Paid'&&!Number(record.depositPaid))add('deposit','financial','Payment status says deposit paid, but the deposit amount is missing');
  if(record.clientChange==='Cancelled'&&!String(record.changeReason||'').trim())add('cancel-reason','change','Cancellation reason is missing');
  if(record.clientChange==='Rescheduled'){
    if(!String(record.changeReason||'').trim())add('reschedule-reason','change','Reschedule reason is missing');
    if(!record.originalDate)add('original-date','change','Original booking date is missing');
    if(!record.originalStart)add('original-start','change','Original booking start time is missing');
  }
  return issues;
}
function bookingAttentionSignature(record){
  return bookingAttentionIssues(record).map(issue=>issue.code).sort().join('|');
}
function bookingAttentionIsResolved(record){
  const signature=bookingAttentionSignature(record);
  return Boolean(signature)&&record.attentionResolvedSignature===signature;
}
function bookingRequiresAttention(record){
  const signature=bookingAttentionSignature(record);
  return Boolean(signature)&&record.attentionResolvedSignature!==signature;
}
function attentionIssueTypeCount(type){
  return masterBookingRecords.filter(record=>
    bookingRequiresAttention(record)&&bookingAttentionIssues(record).some(issue=>issue.type===type)
  ).length;
}
function updateNotificationBadge(){
  const count=masterBookingRecords.filter(bookingRequiresAttention).length;
  const badge=$('notificationCountBadge');
  if(!badge)return;
  badge.textContent=count;
  badge.classList.toggle('zero',count===0);
}
function filteredNotificationBookings(){
  const search=$('notificationSearch').value.trim().toLowerCase();
  const status=$('notificationStatusFilter').value;
  const issueType=$('notificationIssueFilter').value;

  return masterBookingRecords.filter(record=>{
    const issues=bookingAttentionIssues(record);
    if(!issues.length)return false;
    const resolved=bookingAttentionIsResolved(record);
    if(status==='unresolved'&&resolved)return false;
    if(status==='resolved'&&!resolved)return false;
    if(issueType&&!issues.some(issue=>issue.type===issueType))return false;
    const hay=`${record.clientName} ${record.clientPhone} ${record.clientEmail} ${record.reference} ${record.legacyBoatName} ${masterBookingVendorName(record)} ${masterBookingYachtName(record)} ${issues.map(issue=>issue.label).join(' ')}`.toLowerCase();
    return!search||hay.includes(search);
  }).sort((a,b)=>{
    const unresolvedDifference=Number(bookingAttentionIsResolved(a))-Number(bookingAttentionIsResolved(b));
    if(unresolvedDifference)return unresolvedDifference;
    return String(a.date||'9999-12-31').localeCompare(String(b.date||'9999-12-31'))||String(a.start||'99:99').localeCompare(String(b.start||'99:99'));
  });
}
function renderNotificationMetrics(){
  const unresolved=masterBookingRecords.filter(bookingRequiresAttention).length;
  const assignment=attentionIssueTypeCount('assignment');
  const time=attentionIssueTypeCount('time');
  const client=attentionIssueTypeCount('client');
  $('notificationMetrics').innerHTML=[
    ['Requires attention',unresolved,'Unresolved booking warnings'],
    ['Unassigned',assignment,'Missing vendor or yacht'],
    ['Date / time',time,'Incomplete trip schedule'],
    ['Client details',client,'Missing contact or guest details']
  ].map(item=>`<div class="card metric"><span>${item[0]}</span><b>${item[1]}</b><div class="note">${item[2]}</div></div>`).join('');
}
function setBookingAttentionResolved(id,checked){
  const record=masterBookingRecords.find(item=>item.id===id);
  if(!record)return;
  if(checked){
    record.attentionResolvedSignature=bookingAttentionSignature(record);
    record.attentionResolvedAt=new Date().toISOString();
  }else{
    record.attentionResolvedSignature='';
    record.attentionResolvedAt='';
  }
  persist();
  updateNotificationBadge();
  setTimeout(()=>{renderNotificationsDashboard();renderMasterBookingList()},0);
}
function openBookingFromNotification(id){
  setDashboardView('bookings');
  editMasterBookingRecord(id);
}
function renderNotificationList(){
  const records=filteredNotificationBookings();
  const container=$('notificationList');
  if(!records.length){
    const unresolved=masterBookingRecords.filter(bookingRequiresAttention).length;
    container.innerHTML=`<div class="notification-empty">${unresolved?'No notifications match the current filters.':'No bookings currently require attention.'}</div>`;
    return;
  }

  container.innerHTML=records.map(record=>{
    const issues=bookingAttentionIssues(record);
    const resolved=bookingAttentionIsResolved(record);
    const dateText=record.date?readableDate(record.date):'Date missing';
    const timeText=record.start?`${fmtTime(record.start)}${record.end?`–${fmtTime(record.end)}`:' · End time missing'}`:'Time missing';
    return `<article class="notification-card ${resolved?'resolved':''}">
      <div class="notification-card-head">
        <div>
          <div class="notification-card-title">${escapeHtml(record.clientName||'Client name missing')}</div>
          <div class="notification-card-sub">${escapeHtml(dateText)} · ${escapeHtml(timeText)} · ${escapeHtml(masterBookingVendorName(record))} / ${escapeHtml(masterBookingYachtName(record))}</div>
        </div>
        <span class="booking-status ${masterStatusCss(record.status)}">${escapeHtml(record.status)}</span>
      </div>
      <div class="notification-reasons">
        ${issues.map(issue=>`<div class="notification-reason"><span>!</span><span>${escapeHtml(issue.label)}</span></div>`).join('')}
      </div>
      <label class="notification-check" style="margin-top:11px">
        <input class="resolveNotification" data-id="${record.id}" type="checkbox" ${resolved?'checked':''}>
        <span>${resolved?'Reviewed — check again if more work is needed':'Check when reviewed or intentionally completed'}</span>
      </label>
      <div class="notification-actions">
        <button class="primary editNotificationBooking" data-id="${record.id}" type="button">Open and update booking</button>
      </div>
    </article>`;
  }).join('');

  document.querySelectorAll('.resolveNotification').forEach(input=>{
    input.onchange=()=>setBookingAttentionResolved(input.dataset.id,input.checked);
  });
  document.querySelectorAll('.editNotificationBooking').forEach(button=>{
    button.onclick=()=>openBookingFromNotification(button.dataset.id);
  });
}
function renderNotificationsDashboard(){
  updateNotificationBadge();
  renderNotificationMetrics();
  renderNotificationList();
}

function normalizeMasterBookingRecords(data){
  return (Array.isArray(data)?data:[]).map(raw=>({
    id:raw&&raw.id?raw.id:uid('master-booking'),
    clientName:raw&&raw.clientName?raw.clientName:'',
    clientPhone:raw&&raw.clientPhone?raw.clientPhone:'',
    clientEmail:raw&&raw.clientEmail?raw.clientEmail:'',
    reference:raw&&raw.reference?raw.reference:'',
    bookingDate:raw&&raw.bookingDate?raw.bookingDate:'',
    legacyBoatName:raw&&raw.legacyBoatName?raw.legacyBoatName:'',
    customerHourly:Math.max(0,Number(raw&&raw.customerHourly)||0),
    date:raw&&raw.date?raw.date:'',
    start:normalizeHalfHourTime(raw&&raw.start?raw.start:'',false),
    end:normalizeHalfHourTime(raw&&raw.end?raw.end:'',true),
    guestCount:Math.max(0,Math.round(Number(raw&&raw.guestCount)||0)),
    vendorId:raw&&raw.vendorId?raw.vendorId:'',
    yachtId:raw&&raw.yachtId?raw.yachtId:'',
    operator:raw&&raw.operator?raw.operator:'',
    status:['Inquiry','Confirmed','Rescheduled','Completed','Cancelled'].includes(raw&&raw.status)?raw.status:'Inquiry',
    clientChange:['No change','Rescheduled','Cancelled'].includes(raw&&raw.clientChange)
      ?raw.clientChange
      :(raw&&raw.status==='Rescheduled'?'Rescheduled':raw&&raw.status==='Cancelled'?'Cancelled':'No change'),
    changeReason:raw&&raw.changeReason?raw.changeReason:'',
    originalDate:raw&&raw.originalDate?raw.originalDate:'',
    originalStart:normalizeHalfHourTime(raw&&raw.originalStart?raw.originalStart:'',false),
    originalEnd:normalizeHalfHourTime(raw&&raw.originalEnd?raw.originalEnd:'',true),
    customerTotal:Math.max(0,Number(raw&&raw.customerTotal)||0),
    vendorHourly:Math.max(0,Number(raw&&raw.vendorHourly)||0),
    depositPaid:Math.max(0,Number(raw&&raw.depositPaid)||0),
    paymentStatus:['Unpaid','Deposit Paid','Paid in Full','Refunded'].includes(raw&&raw.paymentStatus)?raw.paymentStatus:'Unpaid',
    captainIncluded:['Yes','No','Unknown'].includes(raw&&raw.captainIncluded)?raw.captainIncluded:'Unknown',
    captainPrice:Math.max(0,Number(raw&&raw.captainPrice)||0),
    fuelIncluded:['Yes','No','Unknown'].includes(raw&&raw.fuelIncluded)?raw.fuelIncluded:'Unknown',
    boardingLocation:raw&&raw.boardingLocation?raw.boardingLocation:'',
    behavior:['Not rated','Excellent','Good','Average','Poor','Problem'].includes(raw&&raw.behavior)?raw.behavior:'Not rated',
    notes:raw&&raw.notes?raw.notes:'',
    availabilityId:raw&&raw.availabilityId?raw.availabilityId:'',
    historyId:raw&&raw.historyId?raw.historyId:'',
    attentionResolvedSignature:raw&&raw.attentionResolvedSignature?raw.attentionResolvedSignature:'',
    attentionResolvedAt:raw&&raw.attentionResolvedAt?raw.attentionResolvedAt:'',
    createdAt:raw&&raw.createdAt?raw.createdAt:new Date().toISOString()
  }));
}
function masterBookingVendorName(record){
  const vendor=vendorById(record.vendorId);
  return vendor?vendor.name:'Unassigned vendor';
}
function masterBookingYachtName(record){
  const vendor=vendorById(record.vendorId);
  const yacht=yachtById(vendor,record.yachtId);
  return yacht?displayYachtName(yacht,(vendor.yachts||[]).indexOf(yacht)):(record.legacyBoatName||'Unassigned yacht');
}
function masterBookingDuration(record){
  return availabilityHours(record.start,record.end);
}
function masterVendorCost(record){
  const hourly=masterBookingDuration(record)*(Number(record.vendorHourly)||0);
  const captain=record.captainIncluded==='No'?(Number(record.captainPrice)||0):0;
  return hourly+captain;
}
function masterBalance(record){
  return Math.max(0,(Number(record.customerTotal)||0)-(Number(record.depositPaid)||0));
}
function masterProfit(record){
  return (Number(record.customerTotal)||0)-masterVendorCost(record);
}
function masterStatusCss(status){return String(status||'Inquiry').toLowerCase().replace(/\s+/g,'-')}
function masterPaymentCss(status){return String(status||'Unpaid').toLowerCase().replace(/\s+/g,'-')}
function populateMasterBookingVendorOptions(){
  const form=$('masterBookingVendor'),filter=$('masterBookingVendorFilter');
  if(!form||!filter)return;
  const formValue=form.value,filterValue=filter.value;
  const options=[...vendors].sort((a,b)=>a.name.localeCompare(b.name))
    .map(v=>`<option value="${v.id}">${escapeHtml(v.name)}</option>`).join('');
  form.innerHTML='<option value="">Select vendor</option>'+options;
  filter.innerHTML='<option value="">All vendors</option>'+options;
  if(vendors.some(v=>v.id===formValue))form.value=formValue;
  if(vendors.some(v=>v.id===filterValue))filter.value=filterValue;
}
function populateMasterBookingYachts(useDefaults=false){
  const vendor=vendorById($('masterBookingVendor').value);
  const select=$('masterBookingYacht');
  const previous=select.value;
  if(!vendor){
    select.innerHTML='<option value="">Select vendor first</option>';
    return;
  }
  select.innerHTML='<option value="">Select yacht</option>'+(vendor.yachts||[]).map((y,i)=>
    `<option value="${y.id}">${escapeHtml(displayYachtName(y,i))}${y.price?` — ${money(y.price)}/hr`:''}</option>`
  ).join('');
  if((vendor.yachts||[]).some(y=>y.id===previous))select.value=previous;
  else if((vendor.yachts||[]).length===1)select.value=vendor.yachts[0].id;
  const yacht=yachtById(vendor,select.value);
  if(useDefaults||!$('masterVendorHourly').value)$('masterVendorHourly').value=yacht&&yacht.price?yacht.price:'';
  if(useDefaults||$('masterCaptainIncluded').value==='Unknown')$('masterCaptainIncluded').value=vendor.captainIncluded||'Unknown';
  if(useDefaults||!$('masterCaptainPrice').value)$('masterCaptainPrice').value=vendor.captainPrice||'';
  if(useDefaults||!$('masterBoardingLocation').value)$('masterBoardingLocation').value=vendor.boardingLocation||'';
  updateMasterBookingPreview();
}
function populateMasterBookingOperatorOptions(){
  const select=$('masterBookingOperatorFilter');
  if(!select)return;
  const current=select.value;
  const names=[...new Set(masterBookingRecords.map(r=>String(r.operator||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
  select.innerHTML='<option value="">All operators</option>'+names.map(n=>`<option value="${escapeHtml(n)}">${escapeHtml(n)}</option>`).join('');
  if(names.includes(current))select.value=current;
}
function masterBookingConflicts(record){
  if(!record.vendorId||!record.yachtId||!record.date||!record.start||!record.end||record.status==='Cancelled')return[];
  const startMinutes=timeToMinutes(record.start),endMinutes=timeToMinutes(record.end);
  return masterBookingRecords.filter(other=>{
    if(other.id===record.id||other.status==='Cancelled')return false;
    if(other.vendorId!==record.vendorId||other.yachtId!==record.yachtId||other.date!==record.date)return false;
    const otherStart=timeToMinutes(other.start),otherEnd=timeToMinutes(other.end);
    return startMinutes<otherEnd&&endMinutes>otherStart;
  });
}
function timeToMinutes(value){
  if(!value)return 0;
  if(value==='24:00')return 1440;
  const [h,m]=value.split(':').map(Number);
  return h*60+m;
}
