function ensureManualBookingBase(vendor){
  if(Number.isFinite(Number(vendor.manualCompletedBookingBase)))return;
  const logged=(vendor.bookingHistory||[]).filter(b=>b.status==='Completed').length;
  vendor.manualCompletedBookingBase=Math.max(0,(Number(vendor.completedBookingCount)||0)-logged);
}
function refreshVendorBookingCount(vendor){
  ensureManualBookingBase(vendor);
  const logged=(vendor.bookingHistory||[]).filter(b=>b.status==='Completed').length;
  vendor.completedBookingCount=(Number(vendor.manualCompletedBookingBase)||0)+logged;
  if(vendor.completedBookingCount>0)vendor.bookingRelationship='Booked before';
  else if((vendor.bookingHistory||[]).length)vendor.bookingRelationship='Inquiry only';
  else vendor.bookingRelationship='No booking yet';
}
function reconcileMasterBookingHistory(){
  const touched=new Set();
  masterBookingRecords.forEach(record=>{
    const vendor=vendorById(record.vendorId);if(!vendor)return;
    ensureManualBookingBase(vendor);
    if(!Array.isArray(vendor.bookingHistory))vendor.bookingHistory=[];
    const historyId=record.historyId||`master-history-${record.id}`;
    record.historyId=historyId;
    const entry={
      id:historyId,date:record.date,yachtId:record.yachtId,
      status:record.status==='Completed'?'Completed':record.status==='Cancelled'?'Cancelled':'Pending',
      behavior:record.behavior||'Not rated',reference:record.reference||record.clientName,
      notes:`${record.start?fmtTime(record.start):'Time not added'}${record.end?`–${fmtTime(record.end)}`:''}${record.notes?` · ${record.notes}`:''}`
    };
    const index=vendor.bookingHistory.findIndex(item=>item.id===historyId);
    if(index>=0)vendor.bookingHistory[index]=entry;else vendor.bookingHistory.push(entry);
    touched.add(vendor.id);
  });
  touched.forEach(id=>{
    const vendor=vendorById(id);if(!vendor)return;
    refreshVendorBookingCount(vendor);
    if(vendor.overallBehavior==='Not rated')vendor.overallBehavior=deriveOverallBehavior(vendor);
  });
}

function removeMasterBookingHistory(record){
  if(!record||!record.historyId)return;
  const vendor=vendorById(record.vendorId);
  if(!vendor)return;
  vendor.bookingHistory=(vendor.bookingHistory||[]).filter(b=>b.id!==record.historyId);
  refreshVendorBookingCount(vendor);
  if(vendor.overallBehavior==='Not rated')vendor.overallBehavior=deriveOverallBehavior(vendor);
}
function syncMasterBookingHistory(record,previous=null){
  if(previous&&(previous.vendorId!==record.vendorId)&&previous.historyId)removeMasterBookingHistory(previous);
  const vendor=vendorById(record.vendorId);
  if(!vendor)return;
  ensureManualBookingBase(vendor);
  if(!Array.isArray(vendor.bookingHistory))vendor.bookingHistory=[];
  const historyId=(previous&&previous.vendorId===record.vendorId&&previous.historyId)||record.historyId||uid('booking');
  record.historyId=historyId;
  const status=record.status==='Completed'?'Completed':record.status==='Cancelled'?'Cancelled':'Pending';
  const entry={
    id:historyId,
    date:record.date,
    yachtId:record.yachtId,
    status,
    behavior:record.behavior||'Not rated',
    reference:record.reference||record.clientName,
    notes:`${fmtTime(record.start)}–${fmtTime(record.end)}${record.notes?` · ${record.notes}`:''}`
  };
  const index=vendor.bookingHistory.findIndex(b=>b.id===historyId);
  if(index>=0)vendor.bookingHistory[index]=entry;else vendor.bookingHistory.push(entry);
  refreshVendorBookingCount(vendor);
}
function removeMasterBookingAvailability(record){
  if(!record||!record.availabilityId)return;
  const linked=availabilityRecords.find(a=>a.id===record.availabilityId);
  if(linked)removeAvailabilitySlot(linked);
  availabilityRecords=availabilityRecords.filter(a=>a.id!==record.availabilityId);
  void deleteAvailabilityFromCloud(record.availabilityId);
}
function syncMasterBookingAvailability(record,previous=null){
  const shouldHave=record.status!=='Cancelled'&&record.vendorId&&record.yachtId&&record.date&&record.start&&record.end;
  if(previous&&(previous.vendorId!==record.vendorId||previous.yachtId!==record.yachtId)&&previous.availabilityId){
    removeMasterBookingAvailability(previous);
  }
  if(!shouldHave){
    if(previous)removeMasterBookingAvailability(previous);
    record.availabilityId='';
    return;
  }
  const existingId=(previous&&previous.vendorId===record.vendorId&&previous.yachtId===record.yachtId&&previous.availabilityId)||record.availabilityId||uid('availability');
  const existing=availabilityRecords.find(a=>a.id===existingId)||null;
  const availability={
    id:existingId,
    vendorId:record.vendorId,
    yachtId:record.yachtId,
    date:record.date,
    start:record.start,
    end:record.end,
    price:record.vendorHourly,
    captainIncluded:record.captainIncluded,
    captainPrice:record.captainPrice,
    fuelIncluded:record.fuelIncluded,
    operator:record.operator,
    status:record.status==='Inquiry'?'On Hold':'Booked',
    reference:`Booking: ${record.clientName}${record.reference?` · ${record.reference}`:''}`,
    notes:record.notes,
    slotId:existing&&existing.slotId?existing.slotId:'',
    createdAt:existing&&existing.createdAt?existing.createdAt:new Date().toISOString()
  };
  syncAvailabilitySlot(availability,existing);
  const index=availabilityRecords.findIndex(a=>a.id===existingId);
  if(index>=0)availabilityRecords[index]=availability;else availabilityRecords.push(availability);
  record.availabilityId=existingId;
}
function saveMasterBookingRecord(){
  if(!(canManageBookings()))return denyAction('Your role cannot create or edit bookings.');
  const draft=currentMasterBookingDraft();
  if(!draft.clientName||!draft.date||!draft.start){
    setSaveStatus('masterBookingSaveStatus','Enter the client name, trip date, and start time.',true);
    return;
  }
  if(draft.end&&masterBookingDuration(draft)<=0){
    setSaveStatus('masterBookingSaveStatus','The end time must be later than the start time.',true);
    return;
  }
  const previous=masterBookingRecords.find(r=>r.id===editingMasterBookingId)||null;

  if(draft.clientChange==='Rescheduled'){
    draft.status='Rescheduled';
    if(previous&&!draft.originalDate){
      draft.originalDate=previous.date||'';
      draft.originalStart=previous.start||'';
      draft.originalEnd=previous.end||'';
    }
  }else if(draft.clientChange==='Cancelled'){
    draft.status='Cancelled';
  }

  const record={
    ...draft,
    id:editingMasterBookingId||(previous&&previous.id)||uid('master-booking'),
    availabilityId:previous&&previous.availabilityId?previous.availabilityId:'',
    historyId:previous&&previous.historyId?previous.historyId:'',
    createdAt:previous&&previous.createdAt?previous.createdAt:new Date().toISOString()
  };
  const conflicts=masterBookingConflicts(record);
  if(conflicts.length&&!confirm(`This time overlaps ${conflicts.length} other booking${conflicts.length===1?'':'s'}. Save anyway?`))return;
  syncMasterBookingHistory(record,previous);
  syncMasterBookingAvailability(record,previous);
  const index=masterBookingRecords.findIndex(r=>r.id===record.id);
  if(index>=0)masterBookingRecords[index]=record;else masterBookingRecords.push(record);

  const savedClient=record.clientName||'Booking';
  persist();
  queueBookingCloudSync(record);
  if(record.availabilityId){
    const linkedAvailability=availabilityRecords.find(a=>a.id===record.availabilityId);
    if(linkedAvailability)queueAvailabilityCloudSync(linkedAvailability);
  }
  metrics();
  render();
  renderAvailabilityDashboard();
  renderMasterBookingDashboard();
  renderNotificationsDashboard();

  closeMasterBookingEditor(false);
  setDashboardView('bookings');
  showBookingListBanner(`${savedClient} was saved. The editor is closed and all bookings are shown below.`);
  requestAnimationFrame(()=>{
    if($('bookingListSection'))$('bookingListSection').scrollIntoView({behavior:'smooth',block:'start'});
  });
}
