function deleteMasterBookingRecord(id){
  if(!canDeleteBookings())return denyAction('Your role cannot delete bookings.');
  const record=masterBookingRecords.find(r=>r.id===id);if(!record)return;
  if(!confirm(`Delete the booking for ${record.clientName}?`))return;
  removeMasterBookingAvailability(record);
  removeMasterBookingHistory(record);
  masterBookingRecords=masterBookingRecords.filter(r=>r.id!==id);
  void deleteBookingFromCloud(id);
  if(editingMasterBookingId===id)clearMasterBookingForm();
  persist();metrics();render();renderAvailabilityDashboard();renderMasterBookingDashboard();
}
function filteredMasterBookings(){
  const search=$('masterBookingSearch').value.trim().toLowerCase();
  const vendorId=$('masterBookingVendorFilter').value;
  const date=$('masterBookingDateFilter').value;
  const status=$('masterBookingStatusFilter').value;
  const payment=$('masterPaymentStatusFilter').value;
  const operator=$('masterBookingOperatorFilter').value;
  return [...masterBookingRecords].filter(r=>{
    const hay=`${r.clientName} ${r.clientPhone} ${r.clientEmail} ${r.reference} ${masterBookingVendorName(r)} ${masterBookingYachtName(r)} ${r.operator} ${r.clientChange} ${r.changeReason} ${r.notes}`.toLowerCase();
    return(!search||hay.includes(search))
      &&(!vendorId||r.vendorId===vendorId)
      &&(!date||r.date===date)
      &&(!status||r.status===status)
      &&(!payment||r.paymentStatus===payment)
      &&(!operator||r.operator===operator);
  }).sort((a,b)=>String(a.date).localeCompare(String(b.date))||String(a.start).localeCompare(String(b.start)));
}
function renderMasterBookingMetrics(){
  const active=masterBookingRecords.filter(r=>r.status!=='Cancelled').length;
  const confirmed=masterBookingRecords.filter(r=>['Confirmed','Rescheduled'].includes(r.status)).length;
  const completed=masterBookingRecords.filter(r=>r.status==='Completed').length;
  const value=masterBookingRecords.filter(r=>r.status!=='Cancelled').reduce((sum,r)=>sum+(Number(r.customerTotal)||0),0);
  const outstanding=masterBookingRecords.filter(r=>r.status!=='Cancelled'&&r.paymentStatus!=='Paid in Full').reduce((sum,r)=>sum+masterBalance(r),0);
  $('bookingDashboardMetrics').innerHTML=[
    ['Active bookings',active,'Inquiry, confirmed, rescheduled, and completed'],
    ['Confirmed / rescheduled',confirmed,'Upcoming or active'],
    ['Completed',completed,'Finished bookings'],
    ['Booking value',money(value),'Customer total'],
    ['Outstanding',money(outstanding),'Balance still due']
  ].map(x=>`<div class="card metric"><span>${x[0]}</span><b>${x[1]}</b><div class="note">${x[2]}</div></div>`).join('');
}
