function normalizeAvailabilityRecords(data){
  return (Array.isArray(data)?data:[]).map(raw=>({
    id:raw&&raw.id?raw.id:uid('availability'),
    vendorId:raw&&raw.vendorId?raw.vendorId:'',
    yachtId:raw&&raw.yachtId?raw.yachtId:'',
    date:raw&&raw.date?raw.date:'',
    start:normalizeHalfHourTime(raw&&raw.start?raw.start:'',false),
    end:normalizeHalfHourTime(raw&&raw.end?raw.end:'',true),
    price:Math.max(0,Number(raw&&raw.price)||0),
    captainIncluded:['Yes','No','Unknown'].includes(raw&&raw.captainIncluded)?raw.captainIncluded:'Unknown',
    captainPrice:Math.max(0,Number(raw&&raw.captainPrice)||0),
    fuelIncluded:['Yes','No','Unknown'].includes(raw&&raw.fuelIncluded)?raw.fuelIncluded:'Unknown',
    operator:raw&&raw.operator?raw.operator:'',
    status:['Available','Booked','On Hold','Unavailable'].includes(raw&&raw.status)?raw.status:'Available',
    reference:raw&&raw.reference?raw.reference:'',
    notes:raw&&raw.notes?raw.notes:'',
    slotId:raw&&raw.slotId?raw.slotId:'',
    createdAt:raw&&raw.createdAt?raw.createdAt:new Date().toISOString()
  }));
}
function escapeHtml(value){
  return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
}
function safeMultiline(value){return escapeHtml(value).replace(/\r?\n/g,'<br>')}
function vendorById(id){return vendors.find(v=>v.id===id)||null}
function yachtById(vendor,id){return vendor&&(vendor.yachts||[]).find(y=>y.id===id)||null}
function availabilityHours(start,end){
  if(!start||!end)return 0;
  const [sh,sm]=start.split(':').map(Number),[eh,em]=end.split(':').map(Number);
  return Math.max(0,((eh*60+em)-(sh*60+sm))/60);
}
function availabilityTotal(record){
  const charter=availabilityHours(record.start,record.end)*(Number(record.price)||0);
  const captain=record.captainIncluded==='No'?(Number(record.captainPrice)||0):0;
  return charter+captain;
}
function money(value){
  return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(Number(value)||0);
}
function readableDate(value){
  if(!value)return'Date not added';
  const date=new Date(value+'T12:00:00');
  return date.toLocaleDateString([],{year:'numeric',month:'short',day:'numeric'});
}
function availabilityStatusCss(status){
  return String(status||'Available').toLowerCase().replace(/\s+/g,'-');
}
function availabilityVendorName(record){
  const vendor=vendorById(record.vendorId);
  return vendor?vendor.name:'Removed company';
}
function availabilityYachtName(record){
  const vendor=vendorById(record.vendorId);
  const yacht=yachtById(vendor,record.yachtId);
  return yacht?displayYachtName(yacht,(vendor.yachts||[]).indexOf(yacht)):'Removed yacht';
}
function populateAvailabilityOperatorOptions(){
  const select=$('availabilityOperatorFilter');
  if(!select)return;
  const current=select.value;
  const names=[...new Set(availabilityRecords.map(r=>String(r.operator||'').trim()).filter(Boolean))]
    .sort((a,b)=>a.localeCompare(b));
  select.innerHTML='<option value="">All operators</option>'+names.map(name=>`<option value="${escapeHtml(name)}">${escapeHtml(name)}</option>`).join('');
  if(names.includes(current))select.value=current;
}

function populateAvailabilityCompanyOptions(){
  const form=$('availabilityCompany'),filter=$('availabilityCompanyFilter');
  if(!form||!filter)return;
  const formValue=form.value,filterValue=filter.value;
  const options=[...vendors].sort((a,b)=>a.name.localeCompare(b.name)).map(v=>`<option value="${v.id}">${escapeHtml(v.name)}</option>`).join('');
  form.innerHTML='<option value="">Select company</option>'+options;
  filter.innerHTML='<option value="">All companies</option>'+options;
  if(vendors.some(v=>v.id===formValue))form.value=formValue;
  if(vendors.some(v=>v.id===filterValue))filter.value=filterValue;
}
function populateAvailabilityYachts(useDefaultPrice=false){
  const vendor=vendorById($('availabilityCompany').value);
  const select=$('availabilityYacht');
  const previous=select.value;
  if(!vendor){
    select.innerHTML='<option value="">Select company first</option>';
    return;
  }
  select.innerHTML='<option value="">Select yacht</option>'+(vendor.yachts||[]).map((y,i)=>`<option value="${y.id}">${escapeHtml(displayYachtName(y,i))}${y.price?` — ${money(y.price)}/hr`:''}</option>`).join('');
  if((vendor.yachts||[]).some(y=>y.id===previous))select.value=previous;
  else if((vendor.yachts||[]).length===1)select.value=vendor.yachts[0].id;
  if(useDefaultPrice||!$('availabilityPrice').value){
    const yacht=yachtById(vendor,select.value);
    $('availabilityPrice').value=yacht&&yacht.price?yacht.price:'';
  }
  if(vendor){
    $('availabilityCaptainIncluded').value=vendor.captainIncluded||'Unknown';
    $('availabilityCaptainPrice').value=vendor.captainPrice||'';
  }
  updateAvailabilityTotalPreview();
}
function updateAvailabilityTotalPreview(){
  const hours=availabilityHours($('availabilityStart').value,$('availabilityEnd').value);
  const price=Number($('availabilityPrice').value)||0;
  const captainIncluded=$('availabilityCaptainIncluded').value;
  const captainPrice=captainIncluded==='No'?(Number($('availabilityCaptainPrice').value)||0):0;
  const fuelIncluded=$('availabilityFuelIncluded').value;
  const box=$('availabilityTotalPreview');
  if(!hours||!price){
    box.textContent='Enter the start time, end time, and hourly price.';
    return;
  }
  const charterTotal=hours*price;
  const finalTotal=charterTotal+captainPrice;
  const captainText=captainPrice?` + ${money(captainPrice)} captain`:'';
  const fuelText=fuelIncluded==='Yes'?' · Fuel included':fuelIncluded==='No'?' · Fuel not included':' · Fuel unknown';
  box.textContent=`${hours.toFixed(hours%1?1:0)} hours × ${money(price)}/hour${captainText} = ${money(finalTotal)} total${fuelText}`;
}
function removeAvailabilitySlot(record){
  if(!record||!record.slotId)return;
  const vendor=vendorById(record.vendorId),yacht=yachtById(vendor,record.yachtId);
  if(yacht)yacht.slots=(yacht.slots||[]).filter(slot=>slot.id!==record.slotId);
}
function syncAvailabilitySlot(record,previousRecord=null){
  const moved=previousRecord&&(previousRecord.vendorId!==record.vendorId||previousRecord.yachtId!==record.yachtId);
  if(moved)removeAvailabilitySlot(previousRecord);
  const vendor=vendorById(record.vendorId),yacht=yachtById(vendor,record.yachtId);
  if(!yacht)return;
  const slotId=(!moved&&previousRecord&&previousRecord.slotId)||record.slotId||uid('slot');
  record.slotId=slotId;
  const noteParts=[`Charter price ${money(record.price)}/hr`];
  noteParts.push(`Captain included: ${record.captainIncluded}`);
  if(record.captainIncluded==='No'&&record.captainPrice)noteParts.push(`Captain price ${money(record.captainPrice)}`);
  noteParts.push(`Fuel included: ${record.fuelIncluded}`);
  if(record.operator)noteParts.push(`Operator: ${record.operator}`);
  if(record.reference)noteParts.push(record.reference);
  if(record.notes)noteParts.push(record.notes);
  const slot={id:slotId,date:record.date,start:record.start,end:record.end,status:record.status,note:noteParts.join(' · ')};
  const index=(yacht.slots||[]).findIndex(item=>item.id===slotId);
  if(!Array.isArray(yacht.slots))yacht.slots=[];
  if(index>=0)yacht.slots[index]=slot;else yacht.slots.push(slot);
}
function clearAvailabilityForm(){
  editingAvailabilityId=null;
  $('availabilityFormTitle').textContent='Add availability';
  $('availabilityCompany').value='';
  populateAvailabilityYachts(false);
  ['availabilityDate','availabilityStart','availabilityEnd','availabilityPrice','availabilityCaptainPrice','availabilityOperator','availabilityReference','availabilityNotes'].forEach(id=>$(id).value='');
  $('availabilityStatus').value='Available';
  $('availabilityCaptainIncluded').value='Unknown';
  $('availabilityFuelIncluded').value='Unknown';
  $('availabilitySaveStatus').textContent='';
  updateAvailabilityTotalPreview();
}
function saveAvailabilityRecord(){
  if(!(canManageAvailability()))return denyAction('Your role cannot create or edit availability.');
  const vendorId=$('availabilityCompany').value,yachtId=$('availabilityYacht').value;
  const date=$('availabilityDate').value,
    start=normalizeHalfHourTime($('availabilityStart').value,false),
    end=normalizeHalfHourTime($('availabilityEnd').value,true);
  if(!vendorId||!yachtId||!date||!start||!end){
    setSaveStatus('availabilitySaveStatus','Select the company, yacht, date, start time, and end time.',true);
    return;
  }
  if(availabilityHours(start,end)<=0){
    setSaveStatus('availabilitySaveStatus','The end time must be later than the start time.',true);
    return;
  }
  const previous=availabilityRecords.find(r=>r.id===editingAvailabilityId)||null;
  const record={
    id:editingAvailabilityId||(previous&&previous.id)||uid('availability'),
    vendorId,yachtId,date,start,end,
    price:Math.max(0,Number($('availabilityPrice').value)||0),
    captainIncluded:$('availabilityCaptainIncluded').value,
    captainPrice:Math.max(0,Number($('availabilityCaptainPrice').value)||0),
    fuelIncluded:$('availabilityFuelIncluded').value,
    operator:$('availabilityOperator').value.trim(),
    status:$('availabilityStatus').value,
    reference:$('availabilityReference').value.trim(),
    notes:$('availabilityNotes').value.trim(),
    slotId:previous&&previous.slotId?previous.slotId:'',
    createdAt:previous&&previous.createdAt?previous.createdAt:new Date().toISOString()
  };
  syncAvailabilitySlot(record,previous);
  const index=availabilityRecords.findIndex(r=>r.id===record.id);
  if(index>=0)availabilityRecords[index]=record;else availabilityRecords.push(record);
  persist();render();renderAvailabilityDashboard();populateAvailabilityOperatorOptions();
  queueAvailabilityCloudSync(record);
  setSaveStatus('availabilitySaveStatus',cloudAvailabilitySyncEnabled
    ? `${availabilityVendorName(record)} availability was saved to the shared database.`
    : `${availabilityVendorName(record)} availability was saved. Click Download Updated Dashboard to keep it.`);
  editingAvailabilityId=record.id;
}
function editAvailabilityRecord(id){
  const record=availabilityRecords.find(r=>r.id===id);if(!record)return;
  editingAvailabilityId=id;
  $('availabilityFormTitle').textContent='Edit availability';
  $('availabilityCompany').value=record.vendorId;
  populateAvailabilityYachts(false);
  $('availabilityYacht').value=record.yachtId;
  $('availabilityDate').value=record.date;
  $('availabilityStart').value=record.start;
  $('availabilityEnd').value=record.end;
  $('availabilityPrice').value=record.price||'';
  $('availabilityCaptainIncluded').value=record.captainIncluded||'Unknown';
  $('availabilityCaptainPrice').value=record.captainPrice||'';
  $('availabilityFuelIncluded').value=record.fuelIncluded||'Unknown';
  $('availabilityOperator').value=record.operator||'';
  $('availabilityStatus').value=record.status;
  $('availabilityReference').value=record.reference||'';
  $('availabilityNotes').value=record.notes||'';
  updateAvailabilityTotalPreview();
  $('availabilityEntryCard').scrollIntoView({behavior:'smooth',block:'start'});
}
function deleteAvailabilityRecord(id){
  if(!canManageAvailability())return denyAction('Your role cannot delete availability.');
  const record=availabilityRecords.find(r=>r.id===id);if(!record)return;
  if(!confirm(`Delete the ${availabilityVendorName(record)} availability entry?`))return;
  removeAvailabilitySlot(record);
  availabilityRecords=availabilityRecords.filter(r=>r.id!==id);
  if(editingAvailabilityId===id)clearAvailabilityForm();
  void deleteAvailabilityFromCloud(id);
  persist();render();renderAvailabilityDashboard();
}
function filteredAvailabilityRecords(){
  const search=$('availabilitySearch').value.trim().toLowerCase();
  const vendorId=$('availabilityCompanyFilter').value;
  const date=$('availabilityDateFilter').value;
  const operator=$('availabilityOperatorFilter').value;
  const status=$('availabilityStatusFilter').value;
  return [...availabilityRecords].filter(record=>{
    const hay=`${availabilityVendorName(record)} ${availabilityYachtName(record)} ${record.operator} ${record.reference} ${record.notes}`.toLowerCase();
    return(!search||hay.includes(search))
      &&(!vendorId||record.vendorId===vendorId)
      &&(!date||record.date===date)
      &&(!operator||record.operator===operator)
      &&(!status||record.status===status);
  }).sort((a,b)=>String(a.date).localeCompare(String(b.date))||String(a.start).localeCompare(String(b.start)));
}
function renderAvailabilityMetrics(){
  const available=availabilityRecords.filter(r=>r.status==='Available').length;
  const booked=availabilityRecords.filter(r=>r.status==='Booked').length;
  const bookedRevenue=availabilityRecords.filter(r=>r.status==='Booked').reduce((sum,r)=>sum+availabilityTotal(r),0);
  $('availabilityMetrics').innerHTML=[
    ['Availability entries',availabilityRecords.length,'All saved time slots'],
    ['Available',available,'Open charter slots'],
    ['Booked',booked,'Confirmed charter slots'],
    ['Booked value',money(bookedRevenue),'Estimated charter revenue']
  ].map(x=>`<div class="card metric"><span>${x[0]}</span><b>${x[1]}</b><div class="note">${x[2]}</div></div>`).join('');
}
