function renderAvailabilityDashboard(){
  populateAvailabilityCompanyOptions();
  populateAvailabilityYachts(false);
  populateAvailabilityOperatorOptions();
  renderAvailabilityMetrics();
  renderAvailabilityList();
  applyRoleUi();
}
function setDashboardView(view){
  const availability=view==='availability';
  const bookings=view==='bookings';
  const notifications=view==='notifications';
  const audit=view==='audit';
  const vendorsView=!availability&&!bookings&&!notifications&&!audit;
  $('availabilityDashboardView').classList.toggle('hidden',!availability);
  $('bookingDashboardView').classList.toggle('hidden',!bookings);
  $('notificationsDashboardView').classList.toggle('hidden',!notifications);
  $('auditDashboardView').classList.toggle('hidden',!audit);
  $('vendorDashboardView').classList.toggle('hidden',!vendorsView);
  $('showAvailabilityDashboard').classList.toggle('active',availability);
  $('showBookingDashboard').classList.toggle('active',bookings);
  $('showNotificationsDashboard').classList.toggle('active',notifications);
  $('showAuditDashboard').classList.toggle('active',audit);
  $('showVendorDashboard').classList.toggle('active',vendorsView);
  if(availability)renderAvailabilityDashboard();
  if(bookings)renderMasterBookingDashboard();
  if(notifications)renderNotificationsDashboard();
  if(audit)loadAuditLogs();
}

function displayYachtName(y,index=0){const name=String((y&&y.name)||'').trim();return name||`Yacht ${index+1}`}
function yachtMatches(y){
  const cap=$('capacity').value;
  const minS=num($('minSize').value),maxS=num($('maxSize').value),minP=num($('minPrice').value),maxP=num($('maxPrice').value);
  let cm=true;
  if(cap==='12')cm=y.capacity!==null&&y.capacity<=12;
  if(cap==='13')cm=y.capacity===13;
  if(cap==='20')cm=y.capacity!==null&&y.capacity>=14&&y.capacity<=20;
  const sm=(!minS||(y.length!==null&&y.length>=minS))&&(!maxS||(y.length!==null&&y.length<=maxS));
  const pm=(!minP||(y.price!==null&&y.price>=minP))&&(!maxP||(y.price!==null&&y.price<=maxP));
  return cm&&sm&&pm;
}
function vendorPriceValue(v,highest=false){
  const values=(v.yachts||[]).map(y=>Number(y.price)).filter(x=>Number.isFinite(x)&&x>0);
  if(!values.length)return null;
  return highest?Math.max(...values):Math.min(...values);
}
function vendorLengthValue(v,largest=false){
  const values=(v.yachts||[]).map(y=>Number(y.length)).filter(x=>Number.isFinite(x)&&x>0);
  if(!values.length)return null;
  return largest?Math.max(...values):Math.min(...values);
}
function categoryRank(category){
  return {'Top Guy':1,'Reliable':2,'Expensive':3,'Lazy':4,'Not categorized':5}[category]||6;
}
function reliabilityScore(status){return{'Responsive':3,'Slow':2,'Not Reliable':1,'Not rated':0}[status]||0}
function reliabilityRank(status){return{'Responsive':1,'Slow':2,'Not Reliable':3,'Not rated':4}[status]||5}
function reliabilityCss(status){return String(status||'Not rated').toLowerCase().replace(/\s+/g,'-')}
function completedBookings(v){return Math.max(0,Math.round(Number(v.completedBookingCount)||0))}
function bookingYachtName(v,booking){
  if(!booking||!booking.yachtId)return'Yacht not specified';
  const yacht=(v.yachts||[]).find(y=>y.id===booking.yachtId);
  return yacht?displayYachtName(yacht,(v.yachts||[]).indexOf(yacht)):'Removed yacht';
}
function behaviorCounts(v){
  const counts={Excellent:0,Good:0,Average:0,Poor:0,Problem:0};
  (v.bookingHistory||[]).filter(b=>b.status==='Completed').forEach(b=>{if(counts[b.behavior]!==undefined)counts[b.behavior]++});
  return counts;
}
function behaviorSummaryHtml(v){
  const counts=behaviorCounts(v);
  const parts=Object.entries(counts).filter(([,n])=>n>0).map(([label,n])=>`<span class="behavior-chip">${label}: ${n}</span>`);
  return parts.length?parts.join(''):'<span style="color:var(--muted)">No completed booking feedback</span>';
}
function latestBooking(v){
  const list=[...(v.bookingHistory||[])].filter(b=>b.date).sort((a,b)=>String(b.date).localeCompare(String(a.date)));
  return list[0]||null;
}

function compareNullableNumbers(a,b,direction=1){
  if(a===null&&b===null)return 0;
  if(a===null)return 1;
  if(b===null)return-1;
  return(a-b)*direction;
}
function sortVendorList(list){
  const mode=$('sortVendors').value;
  return [...list].sort((a,b)=>{
    if(mode==='behavior-best')return overallBehaviorRank(a.overallBehavior)-overallBehaviorRank(b.overallBehavior)||completedBookings(b)-completedBookings(a)||reliabilityRank(a.reliabilityStatus)-reliabilityRank(b.reliabilityStatus)||a.name.localeCompare(b.name);
    if(mode==='name-asc')return a.name.localeCompare(b.name);
    if(mode==='category')return categoryRank(a.vendorCategory)-categoryRank(b.vendorCategory)||a.name.localeCompare(b.name);
    if(mode==='reliability')return reliabilityRank(a.reliabilityStatus)-reliabilityRank(b.reliabilityStatus)||completedBookings(b)-completedBookings(a)||a.name.localeCompare(b.name);
    if(mode==='bookings-desc')return completedBookings(b)-completedBookings(a)||reliabilityRank(a.reliabilityStatus)-reliabilityRank(b.reliabilityStatus)||a.name.localeCompare(b.name);
    if(mode==='price-asc')return compareNullableNumbers(vendorPriceValue(a,false),vendorPriceValue(b,false),1)||a.name.localeCompare(b.name);
    if(mode==='price-desc')return compareNullableNumbers(vendorPriceValue(a,true),vendorPriceValue(b,true),-1)||a.name.localeCompare(b.name);
    if(mode==='length-asc')return compareNullableNumbers(vendorLengthValue(a,false),vendorLengthValue(b,false),1)||a.name.localeCompare(b.name);
    if(mode==='length-desc')return compareNullableNumbers(vendorLengthValue(a,true),vendorLengthValue(b,true),-1)||a.name.localeCompare(b.name);
    return(Number(a.sortOrder)||999)-(Number(b.sortOrder)||999)||a.name.localeCompare(b.name);
  });
}
function filteredVendors(){
  const q=$('search').value.trim().toLowerCase();
  const captain=$('captainFilter').value;
  const vendorCategory=$('vendorCategoryFilter').value;
  const reliability=$('reliabilityFilter').value;
  const bookingFilter=$('bookingFilter').value;
  const list=vendors.filter(v=>{
    const yachtText=(v.yachts||[]).map(y=>`${y.name} ${y.category} ${y.capacity||''} ${y.length||''} ${y.price||''} ${y.notes||''}`).join(' ');
    const bookingText=(v.bookingHistory||[]).map(b=>`${b.status} ${b.behavior} ${b.reference||''} ${b.notes||''} ${bookingYachtName(v,b)}`).join(' ');
    const hay=`${v.name} ${v.phone} ${v.email} ${v.vendorCategory||''} ${v.reliabilityStatus||''} ${v.overallBehavior||''} ${v.bookingRelationship||''} ${v.captainName} ${v.boardingLocation} ${v.notes} ${bookingText} ${yachtText}`.toLowerCase();
    const yachts=(v.yachts||[]);
    const anyYacht=!yachts.length?(!num($('minSize').value)&&!num($('maxSize').value)&&!num($('minPrice').value)&&!num($('maxPrice').value)&&!$('capacity').value):yachts.some(yachtMatches);
    return (!q||hay.includes(q))
      &&(!captain||(v.captainIncluded||'Unknown')===captain)
      &&(!vendorCategory||(v.vendorCategory||'Not categorized')===vendorCategory)
      &&(!reliability||(v.reliabilityStatus||'Not rated')===reliability)
      &&(bookingFilter!=='has-bookings'||completedBookings(v)>0)
      &&(bookingFilter!=='no-bookings'||completedBookings(v)===0)
      &&(bookingFilter!=='inquiry-only'||(v.bookingRelationship||'No booking yet')==='Inquiry only')
      &&anyYacht;
  });
  return sortVendorList(list);
}
function preferredYacht(v){
  const yachts=v.yachts||[];
  if(!yachts.length)return null;
  const current=yachts.find(y=>y.id===selectedYachts[v.id]);
  if(current&&yachtMatches(current))return current;
  const matching=yachts.find(yachtMatches)||yachts[0];
  selectedYachts[v.id]=matching.id;
  return matching;
}
function yachtPhotos(v,y){
  const photos=[];
  if(y&&y.profilePhoto)photos.push(y.profilePhoto);
  if(y&&Array.isArray(y.galleryPhotos))y.galleryPhotos.forEach(p=>{if(p)photos.push(p)});
  if(!photos.length&&v.profilePhoto)photos.push(v.profilePhoto);
  if(!photos.length&&Array.isArray(v.galleryPhotos))v.galleryPhotos.forEach(p=>{if(p)photos.push(p)});
  return photos;
}
async function showPhoto(vendorId,direction=0){
  const v=vendors.find(x=>x.id===vendorId);if(!v)return;
  const y=(v.yachts||[]).find(x=>x.id===selectedYachts[v.id])||preferredYacht(v);
  const photos=yachtPhotos(v,y);
  const box=document.querySelector(`[data-photo-box="${vendorId}"]`);
  const count=document.querySelector(`[data-photo-count="${vendorId}"]`);
  if(!box||!count)return;
  if(!photos.length){
    box.textContent=v.name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
    count.textContent='No photos';photoPositions[vendorId]=0;return;
  }
  const current=photoPositions[vendorId]||0;
  const next=(current+direction+photos.length)%photos.length;
  photoPositions[vendorId]=next;
  const ref=photos[next];
  box.textContent='Loading…';
  const url=await imageUrl(ref);
  if(photoPositions[vendorId]!==next)return;
  if(url)box.innerHTML=`<img src="${escapeHtml(url)}" alt="${escapeHtml(v.name)} yacht picture ${next+1}">`;
  else box.textContent='Photo unavailable';
  count.textContent=`${next+1} / ${photos.length}`;
}
function metrics(){
  const yachts=vendors.reduce((n,v)=>n+(v.yachts||[]).length,0);
  const priced=vendors.reduce((n,v)=>n+(v.yachts||[]).filter(y=>y.price).length,0);
  const totalBookings=vendors.reduce((n,v)=>n+completedBookings(v),0);
  const topRated=vendors.filter(v=>v.overallBehavior==='Top Rated').length;
  $('metrics').innerHTML=[['Vendors',vendors.length],['Yachts',yachts],['Completed bookings',totalBookings],['Top-rated vendors',topRated],['Websites',vendors.filter(v=>v.website).length],['Prices known',priced]].map(x=>`<div class="card metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');
}
