function closeYachtEditor(){$('yachtEditor').classList.add('hidden');clearYachtFields()}
function renderSlots(){
  $('slotList').innerHTML=workingSlots.map((s,i)=>`<div class="slot-row"><span>${s.date}</span><span>${fmtTime(s.start)}</span><span>${fmtTime(s.end)}</span><span>${s.status}</span><span>${safeMultiline(s.note||'')}</span><button class="removeSlot" data-i="${i}" type="button">Remove</button></div>`).join('')||'No time slots';
  document.querySelectorAll('.removeSlot').forEach(x=>x.onclick=()=>{workingSlots.splice(+x.dataset.i,1);renderSlots()});
}
function deleteVendor(id){
  if(!canManageVendors())return denyAction('Your role cannot delete vendors.');
  if(!confirm('Delete this vendor, all of its yachts, linked availability, and linked bookings?'))return;
  masterBookingRecords.filter(record=>record.vendorId===id).forEach(record=>removeMasterBookingAvailability(record));
  masterBookingRecords=masterBookingRecords.filter(record=>record.vendorId!==id);
  availabilityRecords=availabilityRecords.filter(record=>record.vendorId!==id);
  vendors=vendors.filter(v=>v.id!==id);
  void deleteVendorFromCloud(id);
  selectedVendors.delete(id);
  persist();metrics();render();renderAvailabilityDashboard();renderMasterBookingDashboard();renderNotificationsDashboard();
}

function generateMessage(){
  const d=$('qDate').value,s=$('qStart').value,e=$('qEnd').value;
  const dateText=d?new Date(d+'T12:00').toLocaleDateString():'[Date]';
  const timeText=s&&e?`${fmtTime(s)} to ${fmtTime(e)}`:s?fmtTime(s):'[Time]';
  const current=queue[queuePos];
  const yachtLine=current&&current.yacht?`\nYacht - ${displayYachtName(current.yacht,(current.vendor.yachts||[]).indexOf(current.yacht))}`:'';
  $('qText').value=`Hello, Is your Boat Available${yachtLine}\nDate - ${dateText}\nTime - ${timeText}`;
}
function buildQueue(){
  return [...selectedVendors].map(id=>{
    const vendor=vendors.find(v=>v.id===id);
    if(!vendor)return null;
    const yacht=(vendor.yachts||[]).find(y=>y.id===selectedYachts[vendor.id])||preferredYacht(vendor);
    return{vendor,yacht};
  }).filter(Boolean);
}
function showQueue(){
  if(queuePos>=queue.length)$('currentRecipient').innerHTML='<b>All selected vendors processed.</b>';
  else{
    const item=queue[queuePos];
    $('currentRecipient').innerHTML=`<b>Next:</b> ${item.vendor.name}<br><b>Yacht:</b> ${item.yacht?displayYachtName(item.yacht,(item.vendor.yachts||[]).indexOf(item.yacht)):'Not selected'}<br>${item.vendor.phone?formatUsPhone(item.vendor.phone):'No phone number'}`;
  }
  $('queueList').innerHTML=queue.map((item,i)=>`${i+1}. ${item.vendor.name} — ${item.yacht?displayYachtName(item.yacht,(item.vendor.yachts||[]).indexOf(item.yacht)):'No yacht'} — ${i<queuePos?'Prepared':i===queuePos?'Next':'Waiting'}`).join('<br>');
  generateMessage();
}

