$('saveYacht').onclick=()=>{
  if(!canManageVendors())return denyAction('Your role cannot save yachts.');
  if(imageUploadPending>0){setSaveStatus('yachtSaveStatus','Please wait until the picture finishes preparing.',true);return;}
  const rawWebsite=$('yWebsite').value.trim();
  if(rawWebsite&&!normalizeWebsiteUrl(rawWebsite)){setSaveStatus('yachtSaveStatus','Enter a valid yacht website, such as https://example.com.',true);return;}
  const name=$('yName').value.trim();
  if(!workingVendor)workingVendor=blankVendor();
  if(!Array.isArray(workingVendor.yachts))workingVendor.yachts=[];
  const yachtId=editingYachtId||(workingYacht&&workingYacht.id)||uid('yacht');
  const y={
    id:yachtId,
    name,
    capacity:num($('yCapacity').value),
    length:num($('yLength').value),
    price:num($('yPrice').value),
    category:$('yCategory').value.trim(),
    website:normalizeWebsiteUrl($('yWebsite').value),
    availability:$('yAvailability').value,
    notes:$('yNotes').value.trim(),
    slots:workingSlots.map(s=>({...s})),
    profilePhoto:yachtProfilePhoto,
    galleryPhotos:[...yachtGalleryPhotos]
  };
  const index=workingVendor.yachts.findIndex(x=>x.id===y.id);
  if(index>=0)workingVendor.yachts[index]=y;
  else workingVendor.yachts.push(y);

  const savedImmediately=persistExistingWorkingVendor();
  renderYachtList();

  if(savedImmediately){
    setSaveStatus('vendorSaveStatus',`${displayYachtName(y,index>=0?index:workingVendor.yachts.length-1)} was updated. Click Download Updated Dashboard to keep it.`);
    closeYachtEditor();
  }else{
    setSaveStatus('yachtSaveStatus',`${displayYachtName(y,workingVendor.yachts.length-1)} was added. Click “Save vendor and close” to finish creating this new vendor.`);
  }
};
$('saveVendor').onclick=()=>{
  if(!canManageVendors())return denyAction('Your role cannot save vendors.');
  if(imageUploadPending>0){setSaveStatus('vendorSaveStatus','Please wait until all pictures finish preparing.',true);return;}
  const rawWebsite=$('fWebsite').value.trim();
  if(rawWebsite&&!normalizeWebsiteUrl(rawWebsite)){setSaveStatus('vendorSaveStatus','Enter a valid vendor website, such as https://example.com.',true);return;}
  const vendor=syncWorkingVendorFromForm();
  if(!vendor.name){
    setSaveStatus('vendorSaveStatus','Vendor name is required.',true);
    return;
  }

  const savedId=vendor.id;
  const index=vendors.findIndex(v=>v.id===editingVendorId);
  if(index>=0)vendors[index]=JSON.parse(JSON.stringify(vendor));
  else{
    vendors.push(JSON.parse(JSON.stringify(vendor)));
    editingVendorId=vendor.id;
  }

  persist();
  queueVendorCloudSync(vendors.find(v=>v.id===savedId));
  closeVendorEditor(false);
  metrics();
  render();
  showVendorCardMessage(savedId,'Vendor, yachts, pictures, reliability, and booking experience were saved.');
};

